import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    int frequency; // Frequency of the word ending at this node

    public TrieNode() {
        frequency = 0;
    }

    public TrieNode getChild(char ch) {
        return children.get(ch);
    }

    public void insertChild(char ch, TrieNode child) {
        children.put(ch, child);
    }
}

public class Trie {
    private TrieNode root;

    public Trie() {
        root = new TrieNode();
    }

    public void insert(String word) {
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            TrieNode child = current.getChild(ch);
            if (child == null) {
                child = new TrieNode();
                current.insertChild(ch, child);
            }
            current = child;
        }
        current.frequency++; // Increment frequency when reaching the end of a word
    }

    public int search(String word) {
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            TrieNode child = current.getChild(ch);
            if (child == null) {
                return 0; // Word not found
            }
            current = child;
        }
        return current.frequency; // Return frequency of the word
    }

    public boolean startsWith(String prefix) {
        TrieNode current = root;
        for (char ch : prefix.toCharArray()) {
            TrieNode child = current.getChild(ch);
            if (child == null) {
                return false; // Prefix not found
            }
            current = child;
        }
        return true; // Prefix found
    }

    public void delete(String word) {
        deleteRecursively(root, word, 0);
    }

    private boolean deleteRecursively(TrieNode current, String word, int index) {
        if (index == word.length()) {
            if (current.frequency > 1) {
                current.frequency--;
                return false; // Word exists and frequency > 1, so don't delete the node
            } else {
                return true; // Word exists and frequency == 1, so delete the node
            }
        }

        char ch = word.charAt(index);
        TrieNode child = current.getChild(ch);
        if (child == null) {
            return false; // Word not found, so don't delete anything
        }

        boolean shouldDeleteChild = deleteRecursively(child, word, index + 1);

        if (shouldDeleteChild) {
            current.children.remove(ch);
            return child.children.isEmpty(); // Return true if the current node should also be deleted
        }

        return false; // Don't delete anything
    }

    public void updateFrequency(String word, int newFrequency) {
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            TrieNode child = current.getChild(ch);
            if (child == null) {
                throw new IllegalArgumentException("Word not found in the Trie");
            }
            current = child;
        }
        current.frequency = newFrequency; // Update frequency of the word
    }

    public static void main(String[] args) {
        Trie trie = new Trie();
        trie.insert("apple");
        trie.insert("app");
        trie.insert("banana");
        System.out.println("Search 'apple': " + trie.search("apple")); // Output: 1
        System.out.println("Search 'app': " + trie.search("app")); // Output: 1
        System.out.println("Search 'banana': " + trie.search("banana")); // Output: 1
        System.out.println("Search 'ban': " + trie.search("ban")); // Output: 0 (not a complete word)
        System.out.println("StartsWith 'app': " + trie.startsWith("app")); // Output: true
        trie.delete("app");
        System.out.println("Search 'app' after deletion: " + trie.search("app")); // Output: 0
        trie.updateFrequency("apple", 3);
        System.out.println("Search 'apple' after update: " + trie.search("apple")); // Output: 3
    }
}
```

